                            if( !haveHiddenItems( $parent ) ){
                                $moreLink.animate({
                                    height: 0
                                }, function(){
                                    $moreLink.css("display", "none");
                                });
                            }

                            if( futureH != currentH ){

                                $list.css({
                                    height: currentH,
                                    overflow: "hidden"
                                });

                                $list.animate({
                                    height: futureH
                                }, function(){
                                    $list.css({  
                                        height: "",
                                        overflow: ""
                                    });

                                    $(document).triggerHandler("unified:BackFill", [{payload: revealedContent}]);
                                })
                            }


                            evt.preventDefault();
                        }
                    }
                );

                function haveHiddenItems( $parent ){
                    var r = false;
                    $(".PartialSimilarQuestions-item", $parent).each( function(){
                        if( $(this).css("display") === "none" ){
                            r = true;
                            return false; 
                        }
                    });
                    return r;
                }

                App.events.push({
                    partial: "PartialSimilarQuestions",
                    contextSelector: ".PartialSimilarQuestions-body",
                    elementSelector: null,
                    type: "ready",
                    handler: function () {

                        if( !haveHiddenItems( $(this) ) ){

                            $(".PartialSimilarQuestions-load-more", $(this)).css("display", "none");
                        }
                    }
                });



                function ellipsizeItem($content) {
                    if ($content.dotdotdot) {

                        var $answer = $content.find(".item-answer");
                        $answer.removeClass("full-length");
                        $answer.dotdotdot({ after: ".PartialSimilarQuestions-answer-link" });
                    }
                }

                App.events.push({
                    partial: "PartialSimilarQuestions",
                    contextSelector: ".PartialSimilarQuestions-body",
                    elementSelector: null,
                    type: "ready",
                    handler: function () {
                        $(".PartialSimilarQuestions-answer").each(function () {
                            ellipsizeItem($(this));
                        });
                    }
                });
            })();
        }
    </script>


