				<article id="post-3153" class="et_pb_post post-3153 post type-post status-publish format-standard has-post-thumbnail hentry category-energy-articles tag-cellular-level tag-disease tag-genetic-diversity tag-genetic-engineering tag-genetic-mutations tag-genetic-research">

                                              <div class="et_post_meta_wrapper">


												</div> <!-- .et_post_meta_wrapper -->

					<div class="entry-content">


<!-- WP QUADS Content Ad Plugin v. 1.1.2 -->
<div class="quads-location" style="float:none;margin:5px 0 5px 0;text-align:center;">
<script async src="//web.archive.org/web/20160507032151js_/http://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js"></script>
