				<aside id="text-2" class="widget margin-bottom20 widget_text">			<div class="textwidget"><script async src="//web.archive.org/web/20160420010739js_/http://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js"></script>
<!-- navajo side -->
<ins class="adsbygoogle" style="display:inline-block;width:300px;height:600px" data-ad-client="ca-pub-9277718084866398" data-ad-slot="8515521579"></ins>
